"use client";
/* eslint-disable @next/next/no-img-element -- QR is an ephemeral data URL generated by the trusted backend. */
import {FormEvent,useEffect,useState} from "react";
import {useRouter} from "next/navigation";
import {beginMFA,completeCustomerMFA,disableMFA,reauthenticate,regenerateRecoveryCodes,revokeAllSessions,securityStatus} from "@/services/customer-api";
type Status={mfa_enabled:boolean;recovery_codes_remaining:number;authentication_level:string};
export function SecurityPanel(){const router=useRouter();const[status,setStatus]=useState<Status|null>(null),[challenge,setChallenge]=useState(""),[qr,setQR]=useState(""),[secret,setSecret]=useState(""),[codes,setCodes]=useState<string[]>([]),[message,setMessage]=useState("");useEffect(()=>{securityStatus().then(setStatus).catch(()=>setMessage("Não foi possível carregar a segurança da conta."))},[]);async function start(){try{const r=await beginMFA();setChallenge(r.challenge_token||"");setQR(r.qr_code_data_url||"");setSecret(r.setup_secret||"")}catch(e){setMessage(e instanceof Error?e.message:"Falha ao iniciar MFA.")}}async function confirm(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);try{const r=await completeCustomerMFA(challenge,String(f.get("code")));sessionStorage.setItem("loja3d_customer_csrf",r.csrf_token);setCodes(r.recovery_codes||[]);setStatus({mfa_enabled:true,recovery_codes_remaining:r.recovery_codes?.length||0,authentication_level:"mfa"})}catch(error){setMessage(error instanceof Error?error.message:"Código inválido.")}}async function sensitive(e:FormEvent<HTMLFormElement>){e.preventDefault();setMessage("");const f=new FormData(e.currentTarget),action=String(f.get("action"));try{const proof=await reauthenticate(String(f.get("password")),String(f.get("code")),String(f.get("recovery_code")));if(action==="disable"){await disableMFA(proof.reauthentication_token);sessionStorage.removeItem("loja3d_customer_csrf");router.push("/login");return}if(action==="regenerate"){const result=await regenerateRecoveryCodes(proof.reauthentication_token);setCodes(result.recovery_codes);setStatus(v=>v&&({...v,recovery_codes_remaining:result.recovery_codes.length}));return}await revokeAllSessions(proof.reauthentication_token);sessionStorage.removeItem("loja3d_customer_csrf");router.push("/login")}catch(error){setMessage(error instanceof Error?error.message:"Reautenticação não concluída.")}}return <section className="security-card"><span className="eyebrow">Segurança</span><h1>Proteção da conta</h1>{status&&<dl><div><dt>MFA</dt><dd>{status.mfa_enabled?"Ativo":"Inativo"}</dd></div><div><dt>Sessão</dt><dd>{status.authentication_level}</dd></div><div><dt>Códigos restantes</dt><dd>{status.recovery_codes_remaining}</dd></div></dl>}{!status?.mfa_enabled&&!challenge&&<button onClick={start}>Ativar autenticador</button>}{challenge&&!codes.length&&<form onSubmit={confirm}>{qr&&<img src={qr} alt="QR Code para configurar o autenticador"/>}<p>Chave manual: <code>{secret}</code></p><label>Código de seis dígitos<input name="code" inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6}" required/></label><button>Confirmar MFA</button></form>}{codes.length>0&&<><h2>Guarde estes códigos</h2><p>Eles são exibidos uma única vez.</p><pre>{codes.join("\n")}</pre></>}{status&&<form onSubmit={sensitive}><h2>Confirmar ação sensível</h2><p>Informe novamente sua senha{status.mfa_enabled?" e o segundo fator":""}. A autorização vale para uma única ação.</p><label>Senha atual<input name="password" type="password" autoComplete="current-password" required/></label>{status.mfa_enabled&&<><label>Código do autenticador<input name="code" inputMode="numeric" autoComplete="one-time-code"/></label><label>Ou código de recuperação<input name="recovery_code" autoComplete="off"/></label></>}<div className="security-actions">{status.mfa_enabled&&<><button name="action" value="regenerate">Gerar novos códigos</button><button className="danger" name="action" value="disable">Desativar MFA</button></>}<button className="danger" name="action" value="revoke">Encerrar todas as sessões</button></div></form>}{message&&<p role="alert">{message}</p>}</section>}
